<?php
declare(strict_types=1);
require_once __DIR__.'/includes/system_update_guard.php';
$systemRoot=nv_system_root(__DIR__);
// Independent portal remains available even if normal source/bootstrap is changing.
if(is_file($systemRoot.'/maintenance.json')){
    $systemApp=__DIR__;$portal=$systemRoot.'/maintenance-portal.php';
    if(is_file($portal)){require $portal;exit;}
    http_response_code(503);exit('Portal pemeliharaan belum tersedia; gunakan recovery CLI.');
}
require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/backup_lib.php';require_once __DIR__.'/includes/system_update.php';require_once __DIR__.'/includes/layout.php';
if(!is_super())deny('Update Sistem hanya untuk Super Admin/Developer yang memakai akun Super Admin.');
$engine=new NaveenaSystemUpdate(APP_DIR);$user=current_user();$err='';$preview=null;$deletePreview=null;
function nv_system_public_record(array $r):array {unset($r['worker_token']);return $r;}
if(isset($_GET['status'])){
    $r=$engine->read((string)$_GET['status']);header('Content-Type: application/json');echo json_encode(nv_system_public_record($r),JSON_UNESCAPED_UNICODE);exit;
}
if(isset($_GET['download'])){
    $r=$engine->read((string)$_GET['download']);if($r['kind']!=='source_backup'||$r['status']!=='success')deny('Backup belum tervalidasi.');
    $path=$engine->root.'/archives/'.$r['id'].'.zip';if(!is_file($path)||hash_file('sha256',$path)!==$r['zip_sha256'])deny('Checksum backup berubah.');
    header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="naveena-source-'.$r['id'].'.zip"');header('Content-Length: '.filesize($path));header('Cache-Control: no-store');readfile($path);exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    try{
        if(in_array($action,['backup','apply','delete'],true)){
            if((int)($_SESSION['system_reauth_lock']??0)>time())throw new RuntimeException('Autentikasi ulang dikunci sementara. Coba lagi setelah 2 menit.');
            if(!password_verify((string)($_POST['password']??''),(string)$user['password_hash'])){$_SESSION['system_reauth_fail']=(int)($_SESSION['system_reauth_fail']??0)+1;if($_SESSION['system_reauth_fail']>=5){$_SESSION['system_reauth_lock']=time()+120;$_SESSION['system_reauth_fail']=0;}throw new RuntimeException('Autentikasi ulang gagal.');}
            unset($_SESSION['system_reauth_fail'],$_SESSION['system_reauth_lock']);
            if(($_POST['confirmation']??'')!=='SAYA SETUJU')throw new RuntimeException('Ketik SAYA SETUJU untuk mengonfirmasi tindakan.');
        }
        if($action==='backup'){$h=$engine->lock();try{$r=$engine->backup((int)$user['id']);}finally{$engine->unlock($h);}audit('Backup Source Code','Update Sistem',null,null,['id'=>$r['id']],'ZIP diverifikasi dan uji restore berhasil');flash('Backup source code berhasil dibuat dan diuji restore.');}
        elseif($action==='delete_preview'){$deletePreview=$engine->read((string)($_POST['id']??''));$blocked=$engine->deletionReason($deletePreview);if($blocked!=='')throw new RuntimeException($blocked);}
        elseif($action==='delete'){$h=$engine->lock();try{$removed=$engine->deleteArchive((string)($_POST['id']??''),(int)$user['id']);}finally{$engine->unlock($h);}audit('Hapus Arsip Sistem','Update Sistem',null,null,['id'=>$removed['id']],'File ZIP/staging dihapus; jurnal dipertahankan');flash('Arsip dihapus. Jurnal audit tetap tersimpan.');}
        elseif($action==='upload'){
            $f=$_FILES['package']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>134217728||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='zip')throw new RuntimeException('Upload ZIP gagal/terlalu besar. Periksa batas upload server.');
            $kind=(string)($_POST['package_kind']??'');if(!in_array($kind,['update','source_backup'],true))throw new RuntimeException('Jenis paket tidak sah.');
            $preview=$engine->stage($f['tmp_name'],$kind,(int)$user['id'],basename($f['name']));$engine->save($preview);
            audit('Validasi Paket Sistem','Update Sistem',null,null,['id'=>$preview['id'],'kind'=>$kind],'Paket ditandatangani, checksum, ekstraksi dan lint diperiksa');
        }elseif($action==='restore_history'){
            $backup=$engine->read((string)($_POST['backup_id']??''));if($backup['kind']!=='source_backup'||$backup['status']!=='success')throw new RuntimeException('Backup tidak sah.');
            $preview=$engine->stage($engine->root.'/archives/'.$backup['id'].'.zip','source_backup',(int)$user['id']);
        }elseif($action==='apply'){
            ignore_user_abort(true);if(function_exists('set_time_limit'))set_time_limit(0);
            $id=(string)($_POST['id']??'');audit('Konfirmasi Instalasi Sistem','Update Sistem',null,null,['id'=>$id],'Autentikasi ulang berhasil; membuat dua snapshot sebelum pemasangan');
            session_write_close();$r=$engine->apply($id,(int)$user['id']);
            if(isset($_POST['async'])){header('Content-Type: application/json');echo json_encode(['ok'=>true,'id'=>$r['id'],'status'=>$r['status']]);exit;}
            flash('Instalasi dan verifikasi sistem berhasil.');
        }else throw new RuntimeException('Tindakan tidak dikenal.');
    }catch(Throwable $e){$err=$e->getMessage();try{audit('Proses Sistem Gagal','Update Sistem',null,null,null,$err);}catch(Throwable $ignored){}
        if(isset($_POST['async'])){http_response_code(422);header('Content-Type: application/json');echo json_encode(['ok'=>false,'error'=>$err]);exit;}
    }
}
$detail=null;if(isset($_GET['detail']))try{$detail=nv_system_public_record($engine->read((string)$_GET['detail']));}catch(Throwable $e){$err=$e->getMessage();}
$retention=null;try{$h=$engine->lock();try{$retention=$engine->pruneSourceBackups((int)$user['id']);}finally{$engine->unlock($h);}}catch(Throwable $ignored){}
$history=$engine->history();$search=trim((string)($_GET['search']??''));$filter=(string)($_GET['filter']??'');$kindFilter=(string)($_GET['kind']??'');
$selected=array_values(array_filter($history,fn($r)=>(!isset($r['deleted_at'])||$filter==='deleted')&&($search===''||stripos(json_encode([$r['id'],$r['package_name']??'',$r['operator']??'',$r['from']??'',$r['to']??'']),$search)!==false)&&($filter===''||($r['status']??'')===$filter)&&($kindFilter===''||($r['kind']??'')===$kindFilter)));
$page=max(1,(int)($_GET['page']??1));$perPage=15;$rows=array_slice($selected,($page-1)*$perPage,$perPage);$last=null;foreach($history as $r)if(in_array($r['kind'],['update','restore'],true)&&in_array($r['status'],['success','restored'],true)){$last=$r;break;}
$versions=['Central'=>db_schema_version_of(db_central_path())];foreach(db_central_all('SELECT id,name FROM branches ORDER BY id') as $b)$versions['Cabang '.$b['id'].' · '.$b['name']]=db_schema_version_of(db_branch_path((int)$b['id']));
page_head('Update Sistem','update_system');page_title('Update Sistem','Update, backup source code, restore, snapshot dan riwayat dalam satu halaman.');
?>
