n-primary">Terapkan <?= $preview['kind']==='update'?'Update':'Restore' ?></button></form><progress class="system-progress" id="system-progress" value="10" max="100"></progress><pre id="system-live" class="system-log" role="status">Paket tervalidasi; menunggu konfirmasi.</pre></div></section><?php endif;?>
<section class="card system-wide"><div class="card-body"><h2>Riwayat Backup Source Code &amp; Update Sistem</h2><p class="small muted">Jumlah Backup Otomatis/manual yang Disimpan: <strong>15</strong>. Arsip tertua dihapus otomatis; jurnal audit tetap tersimpan. Snapshot update terlindungi selama 30 hari dan selama pemulihan.<?= !empty($retention['protected_excess'])?' Ada snapshot terlindungi sehingga jumlah arsip sementara melebihi 15.':'' ?></p><form method="get" class="system-filters"><div class="field"><label for="system-search">Pencarian</label><input class="input" id="system-search" name="search" placeholder="Cari ID, paket, operator, versi" aria-label="Cari riwayat" value="<?= e($search) ?>"></div><div class="field"><label for="system-kind">Jenis</label><select class="input" id="system-kind" name="kind" aria-label="Jenis riwayat"><option value="">Semua jenis</option><?php foreach(['source_backup'=>'Backup Source Code','update'=>'Update Sistem','restore'=>'Restore Source Code'] as $v=>$label):?><option value="<?= e($v) ?>" <?= $kindFilter===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></div><div class="field"><label for="system-status">Status</label><select class="input" id="system-status" name="filter" aria-label="Status"><option value="">Semua status</option><?php foreach(['success','restored','failed','processing','awaiting_confirmation','recovery_required','deleted'] as $s):?><option <?= $filter===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></div><button class="btn">Cari / Filter</button></form><div class="table-wrap"><table class="tbl"><thead><tr><th>ID / Tanggal / Operator</th><th>Jenis / Versi</th><th>ZIP / File / Durasi</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="small"><?= e($r['id']) ?><br><?= e($r['created_at']) ?><br>Operator #<?= (int)($r['operator']??0) ?></td><td><?= e($r['kind']) ?><br><?= e($r['from']??'') ?> → <?= e($r['to']??'') ?></td><td><?= num($r['size']??0) ?> byte<br><?= (int)($r['file_count']??0) ?> file · <?= e($r['duration']??0) ?> detik</td><td><?= badge($r['status'],in_array($r['status'],['success','restored'],true)?'green':'yellow') ?></td><td><div class="system-actions"><a class="btn btn-sm" href="?detail=<?= e($r['id']) ?>">Detail / Log</a><?php if($r['kind']==='source_backup'&&$r['status']==='success'):?><a class="btn btn-sm" href="?download=<?= e($r['id']) ?>">Download Backup</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="restore_history"><input type="hidden" name="backup_id" value="<?= e($r['id']) ?>"><button class="btn btn-sm">Pratinjau Restore</button></form><?php elseif($r['status']==='awaiting_confirmation'):?><span class="small">Upload/pratinjau kembali untuk konfirmasi baru.</span><?php endif;?><?php if(!isset($r['deleted_at'])):$deleteBlocked=$engine->deletionReason($r);?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete_preview"><input type="hidden" name="id" value="<?= e($r['id']) ?>"><button class="btn btn-sm btn-danger" <?= $deleteBlocked!==''?'disabled':'' ?> title="<?= e($deleteBlocked!==''?$deleteBlocked:'Hapus arsip; jurnal audit dipertahankan') ?>">Hapus</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Belum ada riwayat yang cocok.</td></tr><?php endif;?></tbody></table></div><?= pagination(count($selected),$perPage,$page) ?></div></section>
