<script>
const apply=document.getElementById('system-apply');if(apply)apply.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(apply);data.append('async','1');const log=document.getElementById('system-live'),progress=document.getElementById('system-progress');apply.querySelector('button').disabled=true;let tick=setInterval(async()=>{try{const res=await fetch('update_system.php?status='+encodeURIComponent(data.get('id')));const r=await res.json();progress.value=r.progress||0;log.textContent=r.status+'\n'+r.phase+'\n'+(r.error||'');}catch(e){}},2000);try{const res=await fetch('update_system.php',{method:'POST',body:data});const r=await res.json();log.textContent=r.ok?'Pemeriksaan berhasil. Muat ulang untuk melihat riwayat.':r.error;if(r.ok)location.href='update_system.php?detail='+encodeURIComponent(r.id);}catch(e){log.textContent='Koneksi terputus. Periksa status; jangan mengulangi pemasangan. Maintenance tetap aktif bila sistem belum aman.';}finally{clearInterval(tick);}});
</script>
